const now = new Date();
const yesterday = new Date(now - 24 * 60 * 60 * 1000);
const yesterdayStr = yesterday.toISOString().split('T')[0];  // YYYY-MM-DD
const periodStr    = yesterdayStr.substring(0, 7);             // YYYY-MM
const monthStart   = new Date(yesterday.getFullYear(), yesterday.getMonth(), 1).toISOString().split('T')[0];

const apiKeys  = $('Fetch All API Keys').item.json || [];
const history  = $('Fetch 7-Day Consumption History').item.json || [];

// Build 7-day avg per key (daily average over last 7 days)
const histMap = {};
for (const row of history) {
  if (!histMap[row.api_key_id]) histMap[row.api_key_id] = [];
  histMap[row.api_key_id].push(row.cost_eur || 0);
}
const avgMap = {};
for (const [kid, vals] of Object.entries(histMap)) {
  avgMap[kid] = vals.reduce((s, v) => s + v, 0) / 7;  // daily avg
}

return [{ json: { yesterdayStr, periodStr, monthStart, apiKeys, avgMap } }];

const { apiKeys, yesterdayStr, periodStr, monthStart, avgMap } = $input.item.json;

// Group keys by provider
const anthropicKeys = apiKeys.filter(k => k.provider === 'anthropic');
const openaiKeys    = apiKeys.filter(k => k.provider === 'openai');

// Emit one item total — we'll use code nodes to call APIs
return [{ json: { anthropicKeys, openaiKeys, yesterdayStr, periodStr, monthStart, avgMap } }];

// Build llm_consumption insert rows from provider API responses
// and detect anomalies vs 7-day average

const ctx = $('Prepare Date Context').item.json;
const { anthropicKeys, openaiKeys, yesterdayStr, periodStr, monthStart, avgMap } = ctx;

const anthropicRaw = $('Anthropic — Usage API').item.json || {};
const openaiRaw    = $('OpenAI — Usage API').item.json || {};

// EUR/USD exchange rate (static fallback — production would call ECB)
const EUR_USD = 1.075;

const insertRows = [];
const anomalies  = [];

// ── ANTHROPIC ──
// Anthropic usage API returns { data: [{model, input_tokens, output_tokens, ...}] }
const anthropicData = anthropicRaw.data || [];

// Aggregate across models per key (Anthropic doesn't break out by key in basic API)
// We attribute proportionally to registered keys — or if only one key, assign all
let totalAntInputTokens  = 0;
let totalAntOutputTokens = 0;
for (const d of anthropicData) {
  totalAntInputTokens  += d.input_tokens  || 0;
  totalAntOutputTokens += d.output_tokens || 0;
}

// Pricing: claude-sonnet-4-6 — $3/1M input, $15/1M output
const antCostUSD = (totalAntInputTokens / 1e6) * 3 + (totalAntOutputTokens / 1e6) * 15;
const antCostEUR = antCostUSD / EUR_USD;

// Split evenly across registered Anthropic keys (weighted by monthly_budget)
const antTotalBudget = anthropicKeys.reduce((s, k) => s + (k.monthly_budget_eur || 1), 0);
for (const key of anthropicKeys) {
  const weight = (key.monthly_budget_eur || 1) / antTotalBudget;
  const keyCostEUR = antCostEUR * weight;
  const keyInputTokens  = Math.round(totalAntInputTokens  * weight);
  const keyOutputTokens = Math.round(totalAntOutputTokens * weight);

  insertRows.push({
    api_key_id:     key.id,
    provider:       'anthropic',
    model:          'claude-sonnet-4-6',
    period:         periodStr + '-' + yesterdayStr.split('-')[2],  // daily grain
    branch_id:      key.branch_id,
    cost_center_id: key.cost_center_id,
    input_tokens:   keyInputTokens,
    output_tokens:  keyOutputTokens,
    cost_usd:       Math.round(antCostUSD * weight * 100) / 100,
    cost_eur:       Math.round(keyCostEUR * 100) / 100
  });

  // Anomaly check
  const dailyAvg = avgMap[key.id] || 0;
  if (dailyAvg > 0 && keyCostEUR > dailyAvg * 3) {
    anomalies.push({
      api_key_id:    key.id,
      key_ref:       key.key_ref,
      team_name:     key.team_name,
      branch_id:     key.branch_id,
      cost_center_id: key.cost_center_id,
      provider:      'anthropic',
      date:          yesterdayStr,
      cost_eur:      Math.round(keyCostEUR * 100) / 100,
      daily_avg_eur: Math.round(dailyAvg * 100) / 100,
      ratio:         Math.round((keyCostEUR / dailyAvg) * 10) / 10
    });
  }
}

// ── OPENAI ──
const openaiData = openaiRaw.data || [];
// OpenAI usage API: { data: [{aggregation_timestamp, n_requests, operation, snapshot_id, n_context_tokens_total, n_generated_tokens_total}] }
for (const key of openaiKeys) {
  // Sum all models
  let totalInputTokens  = 0;
  let totalOutputTokens = 0;
  for (const d of openaiData) {
    totalInputTokens  += d.n_context_tokens_total   || 0;
    totalOutputTokens += d.n_generated_tokens_total || 0;
  }

  // Pricing: gpt-4o — $2.50/1M input, $10/1M output
  const openaiCostUSD = (totalInputTokens / 1e6) * 2.5 + (totalOutputTokens / 1e6) * 10;
  const openaiCostEUR = openaiCostUSD / EUR_USD;

  insertRows.push({
    api_key_id:     key.id,
    provider:       'openai',
    model:          'gpt-4o',
    period:         periodStr + '-' + yesterdayStr.split('-')[2],
    branch_id:      key.branch_id,
    cost_center_id: key.cost_center_id,
    input_tokens:   totalInputTokens,
    output_tokens:  totalOutputTokens,
    cost_usd:       Math.round(openaiCostUSD * 100) / 100,
    cost_eur:       Math.round(openaiCostEUR * 100) / 100
  });

  const dailyAvg = avgMap[key.id] || 0;
  if (dailyAvg > 0 && openaiCostEUR > dailyAvg * 3) {
    anomalies.push({
      api_key_id:    key.id,
      key_ref:       key.key_ref,
      team_name:     key.team_name,
      branch_id:     key.branch_id,
      cost_center_id: key.cost_center_id,
      provider:      'openai',
      date:          yesterdayStr,
      cost_eur:      Math.round(openaiCostEUR * 100) / 100,
      daily_avg_eur: Math.round(dailyAvg * 100) / 100,
      ratio:         dailyAvg > 0 ? Math.round((openaiCostEUR / dailyAvg) * 10) / 10 : 0
    });
  }
}

return [{ json: { insertRows, anomalies, yesterdayStr, has_anomalies: anomalies.length > 0 } }];

// Build record_spend calls for each branch/cost_center pair
const rows = $('Build Consumption Rows').item.json.insertRows;

// Aggregate by branch_id + cost_center_id
const agg = {};
for (const r of rows) {
  const key = `${r.branch_id}|${r.cost_center_id}`;
  if (!agg[key]) agg[key] = { branch_id: r.branch_id, cost_center_id: r.cost_center_id, total_eur: 0 };
  agg[key].total_eur += r.cost_eur || 0;
}

return Object.values(agg).map(a => ({ json: a }));
